// A StatusOr<T> holds either a usable value of type T, or an error Status
// explaining why such a value is not present. It is a convenient way to return
// either a value or an error from a function.

#pragma once

#include <type_traits>
#include <utility>
#include <variant>

#include "ray/common/status.h"
#include "ray/util/logging.h"

namespace ray {

template <typename T>
class StatusOr {
 public:
  // Allow implicit conversion from other StatusOr<U> where U is convertible to
  // T (e.g. StatusOr<Derived> -> StatusOr<Base>).
  template <typename U>
  friend class StatusOr;

  // Default constructs to an unknown error status.
  StatusOr() : data_(Status::UnknownError("Uninitialized StatusOr.")) {}

  // Implicitly constructible from a Status. The status must not be OK, because
  // an OK status carries no value.
  StatusOr(const Status &status) : data_(status) {  // NOLINT
    RAY_CHECK(!status.ok())
        << "StatusOr cannot be constructed from an OK status without a value.";
  }
  StatusOr(Status &&status) : data_(std::move(status)) {  // NOLINT
    RAY_CHECK(!std::get<Status>(data_).ok())
        << "StatusOr cannot be constructed from an OK status without a value.";
  }

  // Implicitly constructible from a value.
  StatusOr(const T &value) : data_(value) {}       // NOLINT
  StatusOr(T &&value) : data_(std::move(value)) {}  // NOLINT

  StatusOr(const StatusOr &) = default;
  StatusOr(StatusOr &&) = default;
  StatusOr &operator=(const StatusOr &) = default;
  StatusOr &operator=(StatusOr &&) = default;

  // Allow implicit conversion from a StatusOr<U> whose value type U is
  // convertible to T. This enables e.g. StatusOr<Derived> -> StatusOr<Base>.
  template <typename U,
            typename = std::enable_if_t<std::is_convertible_v<U, T> &&
                                        !std::is_same_v<U, T>>>
  StatusOr(const StatusOr<U> &other) {  // NOLINT
    if (other.ok()) {
      data_ = T(std::get<U>(other.data_));
    } else {
      data_ = other.status();
    }
  }

  template <typename U,
            typename = std::enable_if_t<std::is_convertible_v<U, T> &&
                                        !std::is_same_v<U, T>>>
  StatusOr(StatusOr<U> &&other) {  // NOLINT
    if (other.ok()) {
      data_ = T(std::move(std::get<U>(other.data_)));
    } else {
      data_ = std::move(other.status());
    }
  }

  ~StatusOr() = default;

  // Returns true if a value is held.
  bool ok() const { return std::holds_alternative<T>(data_); }

  explicit operator bool() const { return ok(); }

  // Returns the contained status. Returns Status::OK() when a value is held.
  Status status() const {
    if (ok()) {
      return Status::OK();
    }
    return std::get<Status>(data_);
  }

  // Returns the status code.
  StatusCode code() const { return status().code(); }

  // Returns a reference to the contained value. Fatal if no value is held.
  const T &value() const & {
    RAY_CHECK(ok()) << "StatusOr has no value: " << status().ToString();
    return std::get<T>(data_);
  }
  T &value() & {
    RAY_CHECK(ok()) << "StatusOr has no value: " << status().ToString();
    return std::get<T>(data_);
  }
  const T &&value() const && {
    RAY_CHECK(ok()) << "StatusOr has no value: " << status().ToString();
    return std::move(std::get<T>(data_));
  }
  T &&value() && {
    RAY_CHECK(ok()) << "StatusOr has no value: " << status().ToString();
    return std::move(std::get<T>(data_));
  }

  // Dereference operators. Behavior is undefined if no value is held.
  const T &operator*() const & { return std::get<T>(data_); }
  T &operator*() & { return std::get<T>(data_); }
  const T &&operator*() const && { return std::move(std::get<T>(data_)); }
  T &&operator*() && { return std::move(std::get<T>(data_)); }

  const T *operator->() const { return &std::get<T>(data_); }
  T *operator->() { return &std::get<T>(data_); }

  // Returns the value if present, otherwise the provided default.
  template <typename U>
  T value_or(U &&default_val) const & {
    if (ok()) {
      return std::get<T>(data_);
    }
    return static_cast<T>(std::forward<U>(default_val));
  }
  template <typename U>
  T value_or(U &&default_val) && {
    if (ok()) {
      return std::move(std::get<T>(data_));
    }
    return static_cast<T>(std::forward<U>(default_val));
  }

  // Returns the value if present, otherwise a default-constructed T{}.
  T value_or_default() const & {
    if (ok()) {
      return std::get<T>(data_);
    }
    return T{};
  }
  T value_or_default() && {
    if (ok()) {
      return std::move(std::get<T>(data_));
    }
    return T{};
  }

  // If a value is present, invokes f with the value and returns the result.
  // Otherwise returns the error status.
  template <typename F>
  auto and_then(F &&f) const & {
    using Result = std::invoke_result_t<F, const T &>;
    if (ok()) {
      return std::invoke(std::forward<F>(f), std::get<T>(data_));
    }
    return Result(std::get<Status>(data_));
  }
  template <typename F>
  auto and_then(F &&f) && {
    using Result = std::invoke_result_t<F, T &&>;
    if (ok()) {
      return std::invoke(std::forward<F>(f), std::move(std::get<T>(data_)));
    }
    return Result(std::move(std::get<Status>(data_)));
  }

  // If a value is present, returns *this unchanged. Otherwise invokes f with
  // the error status to recover.
  template <typename F>
  auto or_else(F &&f) const & {
    using Result = std::invoke_result_t<F, const Status &>;
    if (ok()) {
      return Result(std::get<T>(data_));
    }
    return std::invoke(std::forward<F>(f), std::get<Status>(data_));
  }
  template <typename F>
  auto or_else(F &&f) && {
    using Result = std::invoke_result_t<F, Status &&>;
    if (ok()) {
      return Result(std::move(std::get<T>(data_)));
    }
    return std::invoke(std::forward<F>(f), std::move(std::get<Status>(data_)));
  }

  void swap(StatusOr &other) { data_.swap(other.data_); }

 private:
  // Holds either the value or the error status.
  std::variant<Status, T> data_;
};

template <typename T>
bool operator==(const StatusOr<T> &lhs, const StatusOr<T> &rhs) {
  if (lhs.ok() != rhs.ok()) {
    return false;
  }
  if (lhs.ok()) {
    return *lhs == *rhs;
  }
  return lhs.code() == rhs.code();
}

template <typename T>
bool operator!=(const StatusOr<T> &lhs, const StatusOr<T> &rhs) {
  return !(lhs == rhs);
}

template <typename T>
void swap(StatusOr<T> &lhs, StatusOr<T> &rhs) {
  lhs.swap(rhs);
}

}  // namespace ray
